export const LANDMARK_COUNT = REAL_PLACES.filter((p) => p.group === "landmark").length;
export const CITY_COUNT = REAL_PLACES.filter((p) => p.group !== "landmark").length;

export function realPlaceId(p: RealPlace): string {
  return `${p.name}|${p.lat.toFixed(4)}|${p.lon.toFixed(4)}`;
}

const BY_ID = new Map<string, RealPlace>();
for (const p of REAL_PLACES) BY_ID.set(realPlaceId(p), p);

export function findRealPlace(id: string): RealPlace | undefined {
  return BY_ID.get(id);
}

export function searchRealPlaces(q: string, group: PlaceGroup | "all" = "all"): RealPlace[] {
  const t = q.trim().toLowerCase();
  const out: RealPlace[] = [];
  for (const p of REAL_PLACES) {
    if (group !== "all" && p.group !== group) continue;
    if (
      t &&
      !p.name.toLowerCase().includes(t) &&
      !p.country.toLowerCase().includes(t) &&
      !p.kind.includes(t)
    ) {
      continue;
    }
    out.push(p);
  }
  return out;
}

